if ~exist('src800','var')
    src800 = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align.sqw');
end
if ~exist('src800sym','var')
    src800sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level %[output:185e24e4]
hc.log_level = -2;
w2_00 = cut(src800,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]); %[output:173ffdee]
plot(w2_00);lz 0 1; keep_figure; %[output:8dec2da2]

w2_00 = cut(src800,line_proj(),0.04,0.04,[-0.1,0.1],[270,280]); %[output:3dc6fd96]
plot(w2_00);lz 0 0.5; keep_figure; %[output:4a5459a9]
%
w2_00 = cut(src800sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]); %[output:56013562]
plot(w2_00);lz 0 1; keep_figure; %[output:7f772893]

w2_00 = cut(src800sym,line_proj(),0.04,0.04,[-0.1,0.1],[270,280]); %[output:3a771081]
plot(w2_00);lz 0 0.5; keep_figure; %[output:23e06d10]

hc.log_level = ll;
%%


othrEi800cut110 = {[-0.1,0.1],[-0.1,0.1],[0,4,500]};
file = src800sym.full_filename %[output:453eb699]
[~,fname] = fileparts(file);

% recover masks not to draw them again
[cuts2fit800NG,masks_file]  = recover_selected_cuts('cuts2fit800NG','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits\');
% retrieve selected cuts used for further fitting
[NG_FFCutsFits,allJfitfile] = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
%%

% make all cuts in <110> directions, around <110> symmetry-related Braggs
% where magnetic form-factor changes minimally.
%
lpM110off110 = line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]);
w2_800off110dirM110 = cut(src800,lpM110off110,[-2,0.04,2],othrEi800cut110{:}); %[output:8501c011]
fh = plot(w2_800off110dirM110);liny; lz 0 0.5; %[output:13631bf3]
[w2_800off110dirM110,cuts2fit800NG] = draw_masks_helper(fh,cuts2fit800NG,'msk110_dirM110',2);
plot(w2_800off110dirM110 );liny; lz 0 1;keep_figure; %[output:13631bf3]

lp110offM110 = line_proj([1,1,0],[1,-1,0],'offset',[-1,1,0]);
w2_800offM110dir110 = cut(src800,lp110offM110,[-1,0.04,2],othrEi800cut110{:}); %[output:1e07e344]
fh = plot(w2_800offM110dir110 );liny; lz 0 0.5; %[output:83366fa8]
[w2_800offM110dir110,cuts2fit800NG] = draw_masks_helper(fh,cuts2fit800NG,'mskM110_dir110',3);
plot(w2_800offM110dir110 );liny; lz 0 1;keep_figure; %[output:83366fa8]

lp110off1M10 = line_proj([1,1,0],[1,-1,0],'offset',[1,-1,0]);
w2_800off1M10dir110 = cut(src800,lp110off1M10,[-1,0.04,2],othrEi800cut110{:}); %[output:0a3d11f9]
fh=plot(w2_800off1M10dir110);lz 0 1; %[output:5d7bf6d0]
[w2_800off1M10dir110,cuts2fit800NG] = draw_masks_helper(fh,cuts2fit800NG,'msk1M10_dir110',3);
plot(w2_800off1M10dir110);liny; lz 0 1;keep_figure; %[output:5d7bf6d0]
%%

%%
w2_800alls = cut(src800sym,line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]),[-1.2,0.04,1.2],othrEi800cut110{:}); %[output:37412e24]
plot(w2_800alls); lz 0 1;keep_figure; %[output:440e4933]

%%
save(masks_file,'cuts2fit800NG');
%%
w2_800 = cut(src800,line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]),[-2,0.04,2],othrEi800cut110{:});
plot(w2_800);lz 0 1;liny; keep_figure %[output:933e7815]
%%
% <110> and <200> cuts min FF change direction
w2ei800NGoff110minFF = sqw_op_bin_pixels({w2_800off110dirM110,w2_800offM110dir110,w2_800off1M10dir110}, ...
    @move_all_to_proj, ...
    {[lpM110off110,lp110offM110,lp110off1M10]}, ...
    lpM110off110,[-2,0.005,2],othrEi800cut110{:},'-combine');
plot(w2ei800NGoff110minFF);liny; lz 0 1;keep_figure; %[output:18e59d8f]
%%
% <110> cut min FF change direction
w2ei800NGoff110minFFfit = cut(w2ei800NGoff110minFF,[0,0.005,0.5],[50,4,250],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(w2ei800NGoff110minFFfit);lz 0 1; keep_figure; %[output:6af38a5a]

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei800_off110NGminFF',w2ei800NGoff110minFFfit);
%%
% specialized <200> offset cut with min FF change
lpm110of200 = line_proj([-1,1,0],[1,1,0],'offset',[2,0,0]);
w2_800NGOff200 = cut(w2ei800NGoff110minFF,lpm110of200,[0,0.005,1],othrEi800cut110{:},SymopReflection('normvec',[1,-1,0],'offset',[1,1,0]));
plot(w2_800NGOff200);lz 0 1; %[output:4a842d03]
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei800_off200NGminFF',cut(w2_800NGOff200,[0,0.005,0.5],[50,4,275]));
%%
%  <110> offset cut with max FF change direction
lp110off110 = line_proj([1,1,0],[1,-1,0],'offset',[1,1,0]);
w2_800off110dir110 = cut(src800sym,lp110off110,[-0.5,0.03,1.5],othrEi800cut110{:}); %[output:214eee94]
fh = plot(w2_800off110dir110);liny; lz 0 2; %[output:55f2f1b1]
[w2_800off110dir110 ,cuts2fit800NG] = draw_masks_helper(fh,cuts2fit800NG,'msk110_dir110',3);
plot(w2_800off110dir110 );liny; lz 0 0.5;keep_figure; %[output:55f2f1b1]
%%
cut2fit = cut(w2_800off110dir110,[0,0.03,0.65],[70,4,330]); %[output:3847dd1a]
plot(cut2fit);liny; lz 0 0.5;keep_figure; %[output:63c02898]
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei800_off110NGmaxFF',cut2fit);
%%

save(masks_file,'cuts2fit800NG');
%%
%  <200> offset cut with max FF change direction
lp110of200 = line_proj([1,1,0],[1,-1,0],'offset',[2,0,0]);
w2_800NGoff200maxFF = cut(src800sym,lp110of200,[0,0.02,1],othrEi800cut110{:}); %[output:76ef6292]
fh = plot(w2_800NGoff200maxFF); liny; lz 0 0.5; %[output:2735fcf5]
[w2_800NGoff200maxFF,cuts2fit800NG] = draw_masks_helper(fh, ...
    cuts2fit800NG, 'msk200_dir110',2);
plot(w2_800NGoff200maxFF); lz 0 0.3; keep_figure; %[output:2735fcf5]

lp110of020 = line_proj([1,1,0],[1,-1,0],'offset',[0,2,0]);
w2_800NGoff020maxFF = cut(src800sym,lp110of020,[0,0.02,1],othrEi800cut110{:}); %[output:1a85bf21]
fh = plot(w2_800NGoff020maxFF); liny; lz 0 0.5; %[output:8fabf355]
[w2_800NGoff020maxFF,cuts2fit800NG] = draw_masks_helper(fh, ...
    cuts2fit800NG, 'msk020_dir110',3);
plot(w2_800NGoff020maxFF); lz 0 0.3; keep_figure; %[output:8fabf355]

w2ei800NGoff200maxFF = sqw_op_bin_pixels({w2_800NGoff200maxFF,w2_800NGoff020maxFF}, ... %[output:group:040e1f73] %[output:8d639e35]
    @move_all_to_proj, ... %[output:8d639e35]
    {[lp110of200,lp110of020]}, ... %[output:8d639e35]
    lp110of200,[0,0.02,0.7],othrEi800cut110{:},'-combine'); %[output:group:040e1f73] %[output:8d639e35]
plot(w2ei800NGoff200maxFF);liny; lz 0 1;keep_figure; %[output:97b88170]
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ... %[output:group:64afaec6] %[output:147f86fd]
    'Ei800_off200NGmaxFF',cut(w2ei800NGoff200maxFF,[0,0.04,0.6],[80,4,395])); %[output:group:64afaec6] %[output:147f86fd]
%%

%%


bg2 = cut(src800,line_proj([-1,1,0],[1,1,0],'offset',[-2,5,0]),[-2,0.04,2],[-0.1,0.1],[-0.1,0.1],[0,5,400]); %[output:0ae22152]
plot(bg2);liny; lz 0 0.1;keep_figure; %[output:40c9e35f]
bg1 = cut(src800,line_proj([-1,1,0],[1,1,0],'offset',[-2,5,0]),[-2,2],[-0.1,0.1],[-0.1,0.1],[0,5,400]); %[output:1f2c74a7]
plot(bg1); logy;keep_figure; %[output:9cba795a]
%%
w2nbg = w2_800 - replicate(bg1,w2_800);
liny; %[output:839e0fbe]
plot(w2nbg); lz 0 1;keep_figure; %[output:602fd3d6]
%%
if ~exist('mi','var')
    mi = MagneticIons();
end
w2nbgc = mi.correct_mag_ff(w2nbg);
plot(w2nbgc); lz 0 1;keep_figure; %[output:2c785d96]
%%
 w2s1 = symmetrise_sqw(w2nbgc,SymopReflection('norm',[-1,1,0],'offset',[0,0,0])) %[output:8281e1b2]
 plot(w2s1); lz 0 1;keep_figure; %[output:4a139e9a]
%%
w2s1 = cut(w2s1,[0,0.01,2],[]); %[output:7cc75e2a]
w2s2 = symmetrise_sqw(w2s1,SymopReflection('norm',[1,-1,0],'offset',[0,2,0])) %[output:21c3993d]
plot(w2s2); lz 0 1;keep_figure; %[output:5a0a3b55]
%%
w2s3 = symmetrise_sqw(w2s2,SymopReflection('norm',[-1,1,0],'offset',[0.5,1.5,0])) %[output:6b514ac2]
w2s3.data.axes.title = "Ei800, one dir; bg removed; ff corrected" %[output:224ae140]
plot(w2s3); lz 0 1;keep_figure; %[output:0644e2b4]

